  // Advance time and frame counter
  time += dt;
  frame++;

  // Calculate rotation
  float rot = atan2(sin(time * speed), cos(time * speed));

  // Paint the pinwheel
  for (int i = 0; i < numSegs; i++) {
    int segIdx = node_seg(i, 0);
    vec3 v1 = led.uv + vec3(0.0, 0.5 * sin(rot + rot * i), 0.0) * segLen / 2.0;
    vec3 v2 = led.uv + vec3(0.0, -0.5 * sin(rot + rot * i), 0.0) * segLen / 2.0;

    // Interpolate between segments
    float t = fract(i / (float)(numSegs - 1));
    name[i].a = floor(t); // segment index
    name[i].b = mix(
      v1, // start of segment
      v2, // end of segment
      t
    );
  }

  // Invert if desired
  if (invert) {
    for (int i = 0; i < numSegs; i++) {
      name[i].b *= -1.0;
    }
  }
}

vec3 shade(Led led) {
