|uniform float speed : 0.0 .. 5.0 = 1.0;

void update() {
}

vec3 shade(Led led) {
    vec2 uv = led.uv;
    float phase = fract(led.s - time * speed);
    float angle = phase * 6.28; // full circle in radians
    float spoke_count = seg_count();
    for (int i = 0; i < spoke_count; ++i) {
        vec3 color = palette1(clamp(mod(i + time, 4), 0.0, 1.0));
        float spoke_angle = angle * (float(i) / spoke_count);
        if (fract(spoke_angle) > 0.5) {
            led.dist += step(spreadstep(led.branch - 2, 2, 4), abs(spoke_angle - 3.14)) ? 0.1 : -0.1;
        }
    }
    return mix(color, palette0(fract(uv)), smoothstep(0.5, 1.0, led.dist));
}

