vec3 shade(Led led) {
    vec2 uv = led.uv;
    fixed t = frac(time);
    if (t < 0.1 || t > 0.9) return vec3(0.0, 0.0, 0.0);
    float amp = mix(0.5, 1.0, smoothstep(0.2, 0.8, fract(t * speed)));
    vec3 color = palette0(mix(0.9, 0.2, t < 0.4 ? 0.7 : 0.3));
    float dist = length(uv - led.uv);
    return clamp(color, 0.0, 1.0) * smoothstep(0.05, 0.1, amp + 0.2 / (dist * dist));
}

